import { $internal } from '../common';
import type { World } from '../world';
import type { Actions, ActionsInitializer, ActionRecord } from './types';

let actionsId = 0;

export function createActions<T extends ActionRecord>(
    initializer: ActionsInitializer<T>
): Actions<T> {
    const id = actionsId++;

    const actions = Object.assign(
        (world: World): T => {
            const ctx = world[$internal];

            // Try array lookup first (faster)
            let instance = ctx.actionInstances[id];

            if (!instance) {
                // Create and cache actions instance
                instance = initializer(world);

                // Ensure array is large enough
                if (id >= ctx.actionInstances.length) {
                    ctx.actionInstances.length = id + 1;
                }
                ctx.actionInstances[id] = instance;
            }

            return instance as T;
        },
        {
            initializer,
        }
    ) as Actions<T>;

    // Add public read-only id property
    Object.defineProperty(actions, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    return actions;
}

export class SparseSet {
    #dense: number[] = [];
    #sparse: number[] = [];
    #cursor: number = 0;

    has(val: number): boolean {
        const index = this.#sparse[val];
        return index < this.#cursor && this.#dense[index] === val;
    }

    add(val: number): void {
        if (this.has(val)) return;
        this.#sparse[val] = this.#cursor;
        this.#dense[this.#cursor++] = val;
    }

    remove(val: number): void {
        if (!this.has(val)) return;
        const index = this.#sparse[val];
        this.#cursor--;
        const swapped = this.#dense[this.#cursor];
        if (swapped !== val) {
            this.#dense[index] = swapped;
            this.#sparse[swapped] = index;
        }
    }

    clear(): void {
        // Clear the sparse array entries for all active values
        for (let i = 0; i < this.#cursor; i++) {
            this.#sparse[this.#dense[i]] = 0;
        }
        this.#cursor = 0;
    }

    sort(): void {
        this.#dense.sort((a, b) => a - b);
        for (let i = 0; i < this.#dense.length; i++) {
            this.#sparse[this.#dense[i]] = i;
        }
    }

    getIndex(val: number): number {
        return this.#sparse[val];
    }

    get dense(): number[] {
        return this.#dense.slice(0, this.#cursor);
    }

    get sparse(): number[] {
        return this.#sparse;
    }
}
