function executeDeferredCommand(world, cmd) {
    const ctx = world[$internal];
    switch (cmd.type) {
        case 'spawn': {
            if (!isEntityAlive(ctx.entityIndex, cmd.entity)) return;
            createEntityFromAllocated(world, cmd.entity, cmd.traits);
