            for (const config of cmd.traits) {
                if (isRelationPair(config)) {
                    const pc = config[$internal];
                    if (typeof pc.target !== 'number') continue;
                    addRelationPairDirect(world, cmd.entity, pc.relation, pc.target, pc.params);
                } else {
                    const t = Array.isArray(config) ? config[0] : config;
                    const params = Array.isArray(config) ? config[1] : undefined;
                    if (hasTraitRaw(world, cmd.entity, t)) {
