```ts
export function fireDeferredSubscriptionDiff(world: World): void {
    const ctx = world[$internal];
    if (!ctx.touchedSubscriptions.size) return;
    for (const rec of ctx.touchedSubscriptions.values()) {
        let post: boolean;
        if (rec.query) {
            post = rec.query.entities.has(rec.entity) && !rec.query.toRemove.has(rec.entity);
        } else if (rec.target !== undefined) {
            const relation = rec.instance!.trait[$internal].relation;
            post = relation ? isPairPresent(ctx, relation, rec.entity, rec.target) : isTraitPresent(ctx, rec.entity, rec.instance!.trait);
        } else {
            post = isTraitPresent(ctx, rec.entity, rec.instance!.trait);
        }
        if (post === rec.pre) continue;
        let subs: Set<(entity: Entity, target?: Entity) => void>;
        if (rec.query) subs = post ? rec.query.addSubscriptions : rec.query.removeSubscriptions;
        else subs = post ? rec.instance!.addSubscriptions : rec.instance!.removeSubscriptions;
        for (const sub of subs) sub(rec.entity, rec.target);
    }
    ctx.touchedSubscriptions.clear();
}
```

