    // Present before the buffer and untouched by it: read the store.
    const eid = getEntityId(entity);
    if (!instance) return { value: undefined };
    if (traitCtx.type === 'aos') return { value: (instance.store as unknown[])[eid] };
    const result: Record<string, unknown> = {};
    const store = instance.store as Record<string, unknown[]>;
    for (const key in store) result[key] = store[key][eid];
    return { value: result };
}

/**
 * The result `entity.has(relation(target))` should report while commands are
 * pending. Returns undefined when the entity has no pending commands.
 */
export function getDeferredPairHas(
    ctx: WorldInternal,
    entity: Entity,
    relation: Relation<Trait>,
    target: RelationTarget
): boolean | undefined {
    const state = replayDeferredState(ctx, entity);
    if (!state) return undefined;
    if (state.destroyed) return false;
    const baseTrait = relation[$internal].trait;
    if (target === '*') return state.traits.has(baseTrait);
    const targets = state.pairs.get(relation);
    return targets ? targets.includes(target) : false;
}

/**
 * The result `entity.get(relation(target))` should report while commands are
 * pending. Returns undefined when the entity has no pending commands.
 */
export function getDeferredPairValue(
    ctx: WorldInternal,
    entity: Entity,
    relation: Relation<Trait>,
    target: Entity
): { value: unknown } | undefined {
    const state = replayDeferredState(ctx, entity);
    if (!state) return undefined;
    if (state.destroyed) return { value: undefined };

    const relationCtx = relation[$internal];
    const baseTrait = relationCtx.trait;
    const targets = state.pairs.get(relation);
    if (!targets || !targets.includes(target)) return { value: undefined };

    const baseCtx = baseTrait[$internal];
    if (baseCtx.type === 'tag') return { value: undefined };

    const instance = getTraitInstance(ctx.traitInstances, baseTrait);
    const key = pairKey(baseTrait.id, target);
    const params = state.pairParams.get(key) ?? (state.spawned ? state.spawnPairParams.get(key) : undefined);

    if (params) {
        if (baseCtx.type === 'aos') return { value: params };
        const defaults = getSchemaDefaults(baseTrait.schema, 'soa');
        return { value: defaults ? { ...defaults, ...params } : params };
    }

    if (state.freshPairs.has(key)) {
        // Added without params: no per-target data will be written.
        if (baseCtx.type === 'aos') return { value: undefined };
        const result: Record<string, unknown> = {};
        for (const keyName in baseTrait.schema) result[keyName] = undefined;
        return { value: result };
    }

    if (!instance || !instance.relationTargets) return { value: undefined };
    const eid = getEntityId(entity);
    let index = -1;
    if (relationCtx.exclusive) {
        index = (instance.relationTargets as Array<Entity | undefined>)[eid] === target ? 0 : -1;
    } else {
        const rawTargets = (instance.relationTargets as number[][])[eid];
        index = rawTargets ? rawTargets.indexOf(target) : -1;
    }
    if (index === -1) return { value: undefined };

    // Present before the buffer: the store data travels with the pair.
    if (baseCtx.type === 'aos') {
        if (relationCtx.exclusive) return { value: (instance.store as unknown[])[eid] };
        return { value: ((instance.store as unknown[][])[eid] ?? [])[index] };
    }
    const result: Record<string, unknown> = {};
    const store = instance.store as Record<string, Array<unknown | unknown[]>>;
    for (const keyName in store) {
        result[keyName] = (store[keyName][eid] as unknown[] | undefined)?.[index];
    }
    return { value: result };
}

/* ------------------------------------------------------------------ *
 * Subscription recording (suppression during flush)
 * ------------------------------------------------------------------ */

/**
 * Fire a subscription now, or record it when a deferred flush is in progress.
 * Recorded events are diffed against the pre-flush state so that each
 * subscription fires at most once, based on the state difference before and
 * after the flush.
 */
export function noteOrFireTraitSubscriptions(
    world: { [$internal]: WorldInternal },
    entity: Entity,
    instance: TraitInstance,
    target: Entity | undefined,
    isAdd: boolean,
    pre: boolean
): void {
    const ctx = world[$internal];
    const subs = isAdd ? instance.addSubscriptions : instance.removeSubscriptions;
    if (ctx.deferredFlushDepth > 0) {
        const key =
            target === undefined
                ? `${entity}:${instance.trait.id}`
                : `${entity}:${instance.trait.id}:${target}`;
        const touched = ctx.deferredTouchedStack[ctx.deferredTouchedStack.length - 1];
        if (!touched.has(key)) {
            touched.set(key, { key, entity, target, instance, pre });
        }
        return;
    }
    for (const sub of subs) sub(entity, target);
}

/**
 * Fire a query subscription now, or record it when a deferred flush is in
 * progress.
 */
export function noteOrFireQuerySubscriptions(
    world: { [$internal]: WorldInternal },
    entity: Entity,
    query: QueryInstance,
    isAdd: boolean,
    pre: boolean
): void {
    const ctx = world[$internal];
    const subs = isAdd ? query.addSubscriptions : query.removeSubscriptions;
    if (ctx.deferredFlushDepth > 0) {
        // No state change to record.
        if (pre) return;
        const key = `q:${entity}:${query.hash}`;
        const touched = ctx.deferredTouchedStack[ctx.deferredTouchedStack.length - 1];
        if (!touched.has(key)) {
            touched.set(key, { key, entity, query, pre });
        }
        return;
    }
    for (const sub of subs) sub(entity);
}

/**
 * Fire the recorded subscription events based on the state difference
 * between before and after the flushed commands.
 */
export function fireDeferredSubscriptionDiff(
    ctx: WorldInternal,
    touched: Map<string, TouchedSubscription>
): void {
    if (touched.size === 0) return;

    for (const rec of touched.values()) {
        let post: boolean;
        if (rec.query) {
            post = rec.query.entities.has(rec.entity) && !rec.query.toRemove.has(rec.entity);
        } else if (rec.target !== undefined && rec.instance) {
            const relation = rec.instance.trait[$internal].relation as Relation<Trait> | null;
            post = relation
                ? isPairPresent(ctx, relation, rec.entity, rec.target)
                : isTraitPresent(ctx, rec.entity, rec.instance.trait);
        } else if (rec.instance) {
            post = isTraitPresent(ctx, rec.entity, rec.instance.trait);
        } else {
            continue;
        }

        if (post === rec.pre) continue;

        const subs = rec.query
            ? post
                ? rec.query.addSubscriptions
                : rec.query.removeSubscriptions
            : post
              ? rec.instance!.addSubscriptions
              : rec.instance!.removeSubscriptions;
        for (const sub of subs) sub(rec.entity, rec.target);
    }

    touched.clear();
}
