import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import type { QueryInstance } from '../query/types';
import type { Relation, RelationPair, RelationTarget } from '../relation/types';
import { isRelationPair } from '../relation/utils/is-relation';
import { getSchemaDefaults } from '../storage/schema';
import { getTraitInstance } from '../trait/trait-instance';
import type {
    ConfigurableTrait,
    Trait,
    TraitInstance,
} from '../trait/types';
import type { WorldInternal } from './types';

/**
 * A single deferred command. Commands are executed in the order they were
 * deferred, across all scopes from oldest to newest.
 */
export type DeferredCommand =
    | { type: 'spawn'; entity: Entity; traits: ConfigurableTrait[] }
    | { type: 'destroy'; entity: Entity }
    | { type: 'add'; entity: Entity; traits: ConfigurableTrait[] }
    | { type: 'remove'; entity: Entity; traits: (Trait | RelationPair)[] }
    | {
          type: 'addExclusive';
          entity: Entity;
          relation: Relation<Trait>;
          target: RelationTarget;
          params?: Record<string, unknown>;
      };

/**
 * A scope is a window of deferred commands (e.g. a single updateEach pass).
 * Scopes flush independently: when a scope is flushed only its own commands
 * execute, leaving commands from other scopes pending.
 */
export type DeferredScope = {
    commands: DeferredCommand[];
    byEntity: Map<Entity, DeferredCommand[]>;
};

/**
 * A subscription event that was recorded during a deferred flush instead of
 * being fired. At the end of the flush the state difference between before
 * and after the flush decides whether (and once) the subscription fires.
 */
export type TouchedSubscription = {
    key: string;
    entity: Entity;
    /** Whether the subscription's subject existed before the recorded change. */
    pre: boolean;
    /** Target entity for relation pair subscriptions. */
    target?: Entity;
    /** Trait instance for trait/pair subscriptions. */
    instance?: TraitInstance;
    /** Query instance for query add/remove subscriptions. */
    query?: QueryInstance;
};

/* ------------------------------------------------------------------ *
 * Pending command lookup
 * ------------------------------------------------------------------ */

/**
 * Concatenated pending commands for an entity, in execution order (scopes
 * from oldest to newest, commands in deferred order).
 * Returns undefined when the entity has no pending commands.
 */
export function getDeferredEntityCommands(
    ctx: WorldInternal,
    entity: Entity
): DeferredCommand[] | undefined {
    if (!ctx.deferredEntitySet.has(entity)) return undefined;
    const commands: DeferredCommand[] = [];
    for (const scope of ctx.deferredScopes) {
        const list = scope.byEntity.get(entity);
        if (!list) continue;
        for (let i = 0; i < list.length; i++) commands.push(list[i]);
    }
    return commands.length > 0 ? commands : undefined;
}

/**
 * True when the entity has a pending deferred destroy (and no pending spawn
 * to nullify it).
 */
export function isEntityDeferredDestroyed(ctx: WorldInternal, entity: Entity): boolean {
    if (!ctx.deferredEntitySet.has(entity)) return false;
    for (const scope of ctx.deferredScopes) {
        const list = scope.byEntity.get(entity);
        if (!list) continue;
        for (let i = 0; i < list.length; i++) {
            if (list[i].type === 'destroy') return true;
        }
    }
    return false;
}

/* ------------------------------------------------------------------ *
 * Raw (unbuffered) state reads
 * ------------------------------------------------------------------ */

/**
 * Read the entity bitmask directly, ignoring any pending deferred commands.
 */
export function isTraitPresent(
    ctx: WorldInternal,
    entity: Entity,
    trait: Trait
): boolean {
    const instance = getTraitInstance(ctx.traitInstances, trait);
    if (!instance) return false;
    const { generationId, bitflag } = instance;
    const mask = ctx.entityMasks[generationId]?.[getEntityId(entity)] ?? 0;
    return (mask & bitflag) === bitflag;
}

/**
 * Read relation targets directly, ignoring any pending deferred commands.
 */
export function isPairPresent(
    ctx: WorldInternal,
    relation: Relation<Trait>,
    entity: Entity,
    target: Entity
): boolean {
    const relationCtx = relation[$internal];
    const instance = getTraitInstance(ctx.traitInstances, relationCtx.trait);
    if (!instance || !instance.relationTargets) return false;
    const eid = getEntityId(entity);
    if (relationCtx.exclusive) {
        return (instance.relationTargets as Array<Entity | undefined>)[eid] === target;
    }
    const targets = (instance.relationTargets as number[][])[eid];
    return targets ? targets.includes(target) : false;
}

/**
 * Read the stored value of a trait directly from the store.
 */
function readRawTraitValue(ctx: WorldInternal, entity: Entity, trait: Trait): unknown {
    const traitCtx = trait[$internal];
    if (traitCtx.type === 'tag') return undefined;
    const instance = getTraitInstance(ctx.traitInstances, trait);
    if (!instance) return undefined;
    const eid = getEntityId(entity);
    if (traitCtx.type === 'aos') return (instance.store as unknown[])[eid];
    const result: Record<string, unknown> = {};
    const store = instance.store as Record<string, unknown[]>;
    for (const key in store) result[key] = store[key][eid];
    return result;
}

