type DeferredReplayState = {
    destroyed: boolean;
    /** The entity was created by a pending deferred spawn. */
    spawned: boolean;
    /** Net trait presence after applying all pending commands. */
    traits: Set<Trait>;
    /** Net relation pairs after applying all pending commands. */
    pairs: Map<Relation<Trait>, Entity[]>;
    /** Final value of every present trait, applied sequentially. */
    traitValues: Map<Trait, unknown>;
    /** Final value of every present pair, applied sequentially. */
    pairValues: Map<string, unknown>;
};

const pairKey = (traitId: number, target: Entity) => `${traitId}:${target}`;

/**
 * The value a freshly added trait will hold (mirrors the immediate
 * addTrait initialization for a brand-new trait).
 */
function freshTraitValue(trait: Trait, params?: Record<string, unknown>): unknown {
    const traitCtx = trait[$internal];
    if (traitCtx.type === 'tag') return undefined;
    if (traitCtx.type === 'aos') {
        return params ?? getSchemaDefaults(trait.schema, 'aos');
    }
    const defaults = getSchemaDefaults(trait.schema, 'soa');
    if (defaults) return { ...defaults, ...(params ?? {}) };
    return params;
}

/**
 * The value a freshly added relation pair will hold (mirrors
 * addRelationPairDirect for a brand-new pair).
 */
function freshPairValue(relation: Relation<Trait>, params?: Record<string, unknown>): unknown {
    const baseTrait = relation[$internal].trait;
    const baseCtx = baseTrait[$internal];
    if (baseCtx.type === 'tag') return undefined;
    const defaults = getSchemaDefaults(baseTrait.schema, baseCtx.type);
    if (defaults) return { ...defaults, ...(params ?? {}) };
    return params;
}

function clearPairsForRelation(state: DeferredReplayState, relation: Relation<Trait>) {
    const baseTrait = relation[$internal].trait;
    const targets = state.pairs.get(relation);
    if (targets) {
        for (let i = 0; i < targets.length; i++) {
            state.pairValues.delete(pairKey(baseTrait.id, targets[i]));
        }
    }
    state.pairs.delete(relation);
    state.traits.delete(baseTrait);
}

