import { $internal } from '../common';
import { destroyEntity, initializeEntity } from '../entity/entity';
import type { Entity } from '../entity/types';
import {
    allocateEntity,
    isEntityAlive,
    releaseEntity,
} from '../entity/utils/entity-index';
import { getRelationTargets } from '../relation/relation';
import type { Relation, RelationPair, RelationTarget } from '../relation/types';
import { $relationPair } from '../relation/symbols';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import {
    addRelationPairDirect,
    addTrait,
    hasTraitRaw,
    removeRelationPairDirect,
    removeTrait,
    setTrait,
} from '../trait/trait';
import type { ConfigurableTrait, Trait } from '../trait/types';
import type { World, WorldInternal } from './types';
import {
    fireDeferredSubscriptionDiff,
    getDeferredEntityCommands,
    type DeferredCommand,
    type DeferredScope,
    type TouchedSubscription,
} from './deferred-state';

/* ------------------------------------------------------------------ *
 * Command buffer state
 * ------------------------------------------------------------------ */

export function createRootDeferredScope(): DeferredScope {
    return { commands: [], byEntity: new Map() };
}

function currentScope(ctx: WorldInternal): DeferredScope {
    return ctx.deferredScopes[ctx.deferredScopes.length - 1];
}

function pushDeferredCommand(ctx: WorldInternal, command: DeferredCommand): void {
    const scope = currentScope(ctx);
    scope.commands.push(command);
    let list = scope.byEntity.get(command.entity);
    if (!list) {
        list = [];
        scope.byEntity.set(command.entity, list);
    }
    list.push(command);
    ctx.deferredEntitySet.add(command.entity);
}

function removeDeferredCommand(ctx: WorldInternal, command: DeferredCommand): void {
    for (const scope of ctx.deferredScopes) {
        const index = scope.commands.indexOf(command);
        if (index === -1) continue;
        scope.commands.splice(index, 1);
        const list = scope.byEntity.get(command.entity);
        if (list) {
            const listIndex = list.indexOf(command);
            if (listIndex !== -1) list.splice(listIndex, 1);
            if (list.length === 0) scope.byEntity.delete(command.entity);
        }
        break;
    }
    if (!getDeferredEntityCommands(ctx, command.entity)) {
        ctx.deferredEntitySet.delete(command.entity);
    }
}

function requeueDeferredCommands(world: World, commands: DeferredCommand[]): void {
    if (commands.length === 0) return;
    const ctx = world[$internal];
    const scope: DeferredScope = { commands, byEntity: new Map() };
    for (const command of commands) {
        let list = scope.byEntity.get(command.entity);
        if (!list) {
            list = [];
            scope.byEntity.set(command.entity, list);
        }
        list.push(command);
    }
    ctx.deferredScopes.push(scope);
    for (const entity of scope.byEntity.keys()) ctx.deferredEntitySet.add(entity);
}

/* ------------------------------------------------------------------ *
 * Scope management
 * ------------------------------------------------------------------ */

/**
 * Push a new deferred scope (e.g. at the start of an updateEach pass).
 */
export function pushDeferredScope(world: World): DeferredScope {
    const scope = createRootDeferredScope();
    world[$internal].deferredScopes.push(scope);
    return scope;
}

/**
 * Detach a scope from the stack and execute its commands. The scope is
 * cleared after execution so that later flushes of the same scope (e.g. the
 * updateEach it was pushed for) are no-ops even if this flush was triggered
 * by a different mechanism.
 */
function detachAndExecuteDeferredScope(world: World, scope: DeferredScope): void {
    const ctx = world[$internal];
    const index = ctx.deferredScopes.indexOf(scope);
    if (index !== -1) ctx.deferredScopes.splice(index, 1);
    if (scope.commands.length === 0) return;
    executeDeferredCommands(world, scope.commands);
    scope.commands.length = 0;
    scope.byEntity.clear();
}

/**
 * Flush the scope (e.g. at the exit of an updateEach pass).
 */
export function flushDeferredScope(world: World, scope: DeferredScope): void {
    detachAndExecuteDeferredScope(world, scope);
}

/**
 * Flush the current (top) scope. A fresh empty scope replaces it so that
 * top-level buffers keep working after a flush.
 */
export function flushTopDeferredScope(world: World): void {
    const ctx = world[$internal];
    const scope = ctx.deferredScopes[ctx.deferredScopes.length - 1];
    if (!scope) return;
    detachAndExecuteDeferredScope(world, scope);
    if (ctx.deferredScopes.length === 0) ctx.deferredScopes.push(createRootDeferredScope());
}

/**
 * Flush every pending scope from oldest to newest. Used by world.reset().
 */
export function flushAllDeferred(world: World): void {
    const ctx = world[$internal];
    while (ctx.deferredScopes.length > 0) {
        detachAndExecuteDeferredScope(world, ctx.deferredScopes[0]);
    }
    ctx.deferredScopes.push(createRootDeferredScope());
}

/**
 * Non-deferred mutations on an entity with pending deferred commands first
 * execute those commands, so earlier-deferred commands always run before
 * later mutations.
 */
export function ensureDeferredFlushForMutation(world: World, entity: Entity): void {
    const ctx = world[$internal];
    if (ctx.deferredFlushDepth > 0) return;
    if (!ctx.deferredEntitySet.has(entity)) return;

    while (true) {
        const index = ctx.deferredScopes.findIndex((scope) => scope.byEntity.has(entity));
        if (index === -1) break;
        detachAndExecuteDeferredScope(world, ctx.deferredScopes[index]);
    }
}

/* ------------------------------------------------------------------ *
 * Execution
 * ------------------------------------------------------------------ */

function cleanDeferredEntitySet(world: World, affected: Set<Entity>): void {
    const ctx = world[$internal];
    for (const entity of affected) {
        if (!getDeferredEntityCommands(ctx, entity)) ctx.deferredEntitySet.delete(entity);
    }
}

export function executeDeferredCommands(world: World, commands: DeferredCommand[]): void {
    const ctx = world[$internal];
    const affected = new Set<Entity>();
    for (const command of commands) affected.add(command.entity);

    ctx.deferredFlushDepth++;
    const touched = new Map<string, TouchedSubscription>();
    ctx.deferredTouchedStack.push(touched);

    let index = 0;
    try {
        for (; index < commands.length; index++) {
            executeDeferredCommand(world, commands[index]);
        }
    } catch (error) {
        // Keep the commands that never ran pending in a new scope.
        requeueDeferredCommands(world, commands.slice(index));
        ctx.deferredTouchedStack.pop();
        fireDeferredSubscriptionDiff(ctx, touched);
        cleanDeferredEntitySet(world, affected);
        ctx.deferredFlushDepth--;
        throw error;
    }

    ctx.deferredTouchedStack.pop();
    fireDeferredSubscriptionDiff(ctx, touched);
    cleanDeferredEntitySet(world, affected);
    ctx.deferredFlushDepth--;
}

function executeDeferredCommand(world: World, command: DeferredCommand): void {
    const ctx = world[$internal];

    switch (command.type) {
        case 'spawn': {
            // The entity slot was allocated when the command was deferred; a
            // destroyed slot means it was recycled and must be skipped.
            if (!isEntityAlive(ctx.entityIndex, command.entity)) return;
            initializeEntity(world, command.entity, command.traits);
            return;
        }
        case 'destroy': {
            if (command.entity === ctx.worldEntity) {
                throw new Error('Koota: The world entity cannot be destroyed.');
            }
            if (!isEntityAlive(ctx.entityIndex, command.entity)) return;
            destroyEntity(world, command.entity);
            return;
        }
        case 'add': {
            if (!isEntityAlive(ctx.entityIndex, command.entity)) return;
            for (const config of command.traits) {
                if (isPlainParams(config)) continue;
                if (isRelationPair(config)) {
                    const pairCtx = config[$internal];
                    const target = pairCtx.target;
                    // Only specific targets can be added (not wildcard '*').
                    if (typeof target !== 'number') continue;
                    addRelationPairDirect(
                        world,
                        command.entity,
                        pairCtx.relation as Relation<Trait>,
                        target,
                        pairCtx.params
                    );
                    continue;
                }
                const trait = Array.isArray(config) ? config[0] : config;
                const params = Array.isArray(config) ? config[1] : undefined;
                if (hasTraitRaw(world, command.entity, trait)) {
                    // Later values for the same trait replace earlier ones.
                    if (params !== undefined) replaceDeferredValue(world, command.entity, trait, params);
                } else {
                    addTrait(world, command.entity, config);
                }
            }
            return;
        }
        case 'remove': {
            if (!isEntityAlive(ctx.entityIndex, command.entity)) return;
            for (const trait of command.traits) removeTrait(world, command.entity, trait);
            return;
        }
        case 'addExclusive': {
            if (!isEntityAlive(ctx.entityIndex, command.entity)) return;
            const { relation, target, params } = command;
            if (target === '*') {
                // Wildcard clears all pairs.
                removeRelationPairDirect(world, command.entity, relation, '*');
            } else {
                // Replace all existing pairs with the single new one.
                const existing = getRelationTargets(world, relation, command.entity);
                for (const existingTarget of existing) {
                    removeRelationPairDirect(world, command.entity, relation, existingTarget);
                }
                addRelationPairDirect(world, command.entity, relation, target, params);
            }
            return;
        }
    }
}

/**
 * Replace the value of an already-present trait (deferred "replace"
 * semantics). Mirrors what a fresh add with params would write.
 */
function replaceDeferredValue(
    world: World,
    entity: Entity,
    trait: Trait,
    params: Record<string, unknown>
): void {
    const traitCtx = trait[$internal];
    if (traitCtx.type === 'tag') return;
    // For soa traits only the fields present in params are written, so the
    // later values replace the earlier ones field by field; for aos the new
    // value replaces the stored object wholesale.
    setTrait(world, entity, trait, params, false);
}

/* ------------------------------------------------------------------ *
 * Public deferred API
 * ------------------------------------------------------------------ */

/** A config accepted by the loose forms of the deferred API. */
export type DeferredConfig = ConfigurableTrait | Record<string, unknown>;

export type Deferred = {
    spawn: (...traits: DeferredConfig[]) => Entity;
    destroy: (entity: Entity) => void;
    add: (entity: Entity, ...traits: DeferredConfig[]) => void;
    remove: (entity: Entity, ...traits: (Trait | RelationPair)[]) => void;
    addExclusive: (
        entity: Entity,
        relationOrPair: Relation<Trait> | RelationPair,
        target?: RelationTarget,
        params?: Record<string, unknown>
    ) => void;
    flush: () => void;
};

/**
 * A plain params object (not an array, not a relation pair).
 */
function isPlainParams(value: unknown): value is Record<string, unknown> {
    return (
        typeof value === 'object' && value !== null && !Array.isArray(value) && !isRelationPair(value)
    );
}

function isBareTrait(value: unknown): value is Trait {
    return typeof value === 'function' && !isRelation(value);
}

/**
 * Accept the loose `T, params` and `relation(target), params` call forms by
 * merging a plain params object into the config that precedes it.
 */
function normalizeDeferredConfigs(configs: unknown[]): ConfigurableTrait[] {
    const out: ConfigurableTrait[] = [];
    for (const config of configs) {
        if (isPlainParams(config) && out.length > 0) {
            const prev = out[out.length - 1];
            if (isBareTrait(prev)) {
                out[out.length - 1] = [prev, config];
                continue;
            }
            if (Array.isArray(prev) && isBareTrait(prev[0])) {
                const [trait, params] = prev;
                out[out.length - 1] = [trait, { ...params, ...config }];
                continue;
            }
            if (isRelationPair(prev)) {
                const pairCtx = prev[$internal];
                out[out.length - 1] = {
                    [$relationPair]: true,
                    [$internal]: {
                        relation: pairCtx.relation,
                        target: pairCtx.target,
                        params: { ...pairCtx.params, ...config },
                    },
                };
                continue;
            }
        }
        out.push(config as ConfigurableTrait);
    }
    return out;
}

export function createDeferredBuffer(world: World): Deferred {
    return {
        spawn(...traits: DeferredConfig[]): Entity {
            const ctx = world[$internal];
            // Allocate the slot eagerly so the caller receives a usable entity
            // reference before the buffer flushes. Traits and query
            // registrations are applied when the command executes.
            const entity = allocateEntity(ctx.entityIndex);
            pushDeferredCommand(ctx, { type: 'spawn', entity, traits: normalizeDeferredConfigs(traits) });
            return entity;
        },

        destroy(entity: Entity) {
            const ctx = world[$internal];
            // A spawn and a destroy in the same buffer nullify each other:
            // the entity is never created, so both commands are dropped and
            // the eagerly-allocated slot is released.
            const commands = getDeferredEntityCommands(ctx, entity);
            if (commands) {
                const spawn = commands.find((command) => command.type === 'spawn');
                if (spawn) {
                    removeDeferredCommand(ctx, spawn);
                    releaseEntity(ctx.entityIndex, entity);
                    return;
                }
            }
            pushDeferredCommand(ctx, { type: 'destroy', entity });
        },

        add(entity: Entity, ...traits: DeferredConfig[]) {
            pushDeferredCommand(world[$internal], {
                type: 'add',
                entity,
                traits: normalizeDeferredConfigs(traits),
            });
        },

        remove(entity: Entity, ...traits: (Trait | RelationPair)[]) {
            pushDeferredCommand(world[$internal], { type: 'remove', entity, traits });
        },

        addExclusive(
            entity: Entity,
            relationOrPair: Relation<Trait> | RelationPair,
            target?: RelationTarget,
            params?: Record<string, unknown>
        ) {
            let relation: Relation<Trait>;
            let pairTarget: RelationTarget | undefined;
            let pairParams: Record<string, unknown> | undefined;

            if (isRelationPair(relationOrPair)) {
                const pairCtx = relationOrPair[$internal];
                relation = pairCtx.relation as Relation<Trait>;
                pairTarget = pairCtx.target;
                pairParams = pairCtx.params;
            } else {
                relation = relationOrPair;
                pairTarget = target;
                pairParams = params;
            }

            if (pairTarget === undefined) {
                throw new Error('Koota: The relation target is undefined.');
            }

            pushDeferredCommand(world[$internal], {
                type: 'addExclusive',
                entity,
                relation,
                target: pairTarget,
                params: pairParams,
            });
        },

        flush() {
            flushTopDeferredScope(world);
        },
    };
}

