+        if (relationCtx.exclusive) return (instance.store as unknown[])[eid];
+        return ((instance.store as unknown[][])[eid] ?? [])[index];
+    }
+    const result: Record<string, unknown> = {};
+    const store = instance.store as Record<string, Array<unknown | unknown[]>>;
+    for (const keyName in store) {
+        result[keyName] = (store[keyName][eid] as unknown[] | undefined)?.[index];
+    }
