+ * Returns undefined when the entity has no pending commands.
+ */
+export function getDeferredTraitValue(
+    ctx: WorldInternal,
+    entity: Entity,
+    trait: Trait
+): { value: unknown } | undefined {
+    const state = replayDeferredState(ctx, entity);
+    if (!state) return undefined;
+    if (state.destroyed || !state.traits.has(trait)) return { value: undefined };
+
+    const traitCtx = trait[$internal];
+    if (traitCtx.type === 'tag') return { value: undefined };
+    return { value: state.traitValues.get(trait) };
