+    if (state.destroyed) return false;
+    const baseTrait = relation[$internal].trait;
+    if (target === '*') return state.traits.has(baseTrait);
+    const targets = state.pairs.get(relation);
+    return targets ? targets.includes(target) : false;
+}
+
+/**
