+ * Subscription recording (suppression during flush)
+ * ------------------------------------------------------------------ */
+
+/**
+ * Fire a subscription now, or record it when a deferred flush is in progress.
+ * Recorded events are diffed against the pre-flush state so that each
+ * subscription fires at most once, based on the state difference before and
+ * after the flush.
+ */
+export function noteOrFireTraitSubscriptions(
+    world: { [$internal]: WorldInternal },
+    entity: Entity,
+    instance: TraitInstance,
+    target: Entity | undefined,
+    isAdd: boolean,
+    pre: boolean
+): void {
+    const ctx = world[$internal];
+    const subs = isAdd ? instance.addSubscriptions : instance.removeSubscriptions;
+    if (ctx.deferredFlushDepth > 0) {
+        const key =
+            target === undefined
+                ? `${entity}:${instance.trait.id}`
+                : `${entity}:${instance.trait.id}:${target}`;
+        const touched = ctx.deferredTouchedStack[ctx.deferredTouchedStack.length - 1];
+        if (!touched.has(key)) {
+            touched.set(key, { key, entity, target, instance, pre });
+        }
+        return;
+    }
+    for (const sub of subs) sub(entity, target);
+}
+
+/**
+ * Fire a query subscription now, or record it when a deferred flush is in
+ * progress.
+ */
+export function noteOrFireQuerySubscriptions(
+    world: { [$internal]: WorldInternal },
+    entity: Entity,
+    query: QueryInstance,
+    isAdd: boolean,
+    pre: boolean
+): void {
+    const ctx = world[$internal];
+    const subs = isAdd ? query.addSubscriptions : query.removeSubscriptions;
+    if (ctx.deferredFlushDepth > 0) {
+        // No state change to record.
+        if (pre) return;
+        const key = `q:${entity}:${query.hash}`;
+        const touched = ctx.deferredTouchedStack[ctx.deferredTouchedStack.length - 1];
+        if (!touched.has(key)) {
+            touched.set(key, { key, entity, query, pre });
+        }
+        return;
+    }
+    for (const sub of subs) sub(entity);
+}
+
+/**
+ * Fire the recorded subscription events based on the state difference
+ * between before and after the flushed commands.
+ */
+export function fireDeferredSubscriptionDiff(
+    ctx: WorldInternal,
+    touched: Map<string, TouchedSubscription>
+): void {
+    if (touched.size === 0) return;
+
+    for (const rec of touched.values()) {
+        let post: boolean;
+        if (rec.query) {
+            post = rec.query.entities.has(rec.entity) && !rec.query.toRemove.has(rec.entity);
+        } else if (rec.target !== undefined && rec.instance) {
+            const relation = rec.instance.trait[$internal].relation as Relation<Trait> | null;
+            post = relation
+                ? isPairPresent(ctx, relation, rec.entity, rec.target)
+                : isTraitPresent(ctx, rec.entity, rec.instance.trait);
+        } else if (rec.instance) {
+            post = isTraitPresent(ctx, rec.entity, rec.instance.trait);
+        } else {
+            continue;
+        }
+
+        if (post === rec.pre) continue;
+
+        const subs = rec.query
+            ? post
+                ? rec.query.addSubscriptions
+                : rec.query.removeSubscriptions
+            : post
+              ? rec.instance!.addSubscriptions
+              : rec.instance!.removeSubscriptions;
+        for (const sub of subs) sub(rec.entity, rec.target);
+    }
+
+    touched.clear();
+}
