@@ -0,0 +1,623 @@
+import { $internal } from '../common';
+import type { Entity } from '../entity/types';
+import { getEntityId } from '../entity/utils/pack-entity';
+import type { QueryInstance } from '../query/types';
+import type { Relation, RelationPair, RelationTarget } from '../relation/types';
+import { isRelationPair } from '../relation/utils/is-relation';
+import { getSchemaDefaults } from '../storage/schema';
+import { getTraitInstance } from '../trait/trait-instance';
+import type {
+    ConfigurableTrait,
+    Trait,
+    TraitInstance,
+} from '../trait/types';
+import type { WorldInternal } from './types';
+
+/**
+ * A single deferred command. Commands are executed in the order they were
+ * deferred, across all scopes from oldest to newest.
+ */
+export type DeferredCommand =
+    | { type: 'spawn'; entity: Entity; traits: ConfigurableTrait[] }
+    | { type: 'destroy'; entity: Entity }
+    | { type: 'add'; entity: Entity; traits: ConfigurableTrait[] }
+    | { type: 'remove'; entity: Entity; traits: (Trait | RelationPair)[] }
+    | {
+          type: 'addExclusive';
+          entity: Entity;
+          relation: Relation<Trait>;
+          target: RelationTarget;
+          params?: Record<string, unknown>;
+      };
+
+/**
+ * A scope is a window of deferred commands (e.g. a single updateEach pass).
+ * Scopes flush independently: when a scope is flushed only its own commands
+ * execute, leaving commands from other scopes pending.
+ */
+export type DeferredScope = {
+    commands: DeferredCommand[];
+    byEntity: Map<Entity, DeferredCommand[]>;
+};
+
+/**
+ * A subscription event that was recorded during a deferred flush instead of
+ * being fired. At the end of the flush the state difference between before
+ * and after the flush decides whether (and once) the subscription fires.
+ */
+export type TouchedSubscription = {
+    key: string;
+    entity: Entity;
+    /** Whether the subscription's subject existed before the recorded change. */
+    pre: boolean;
+    /** Target entity for relation pair subscriptions. */
+    target?: Entity;
+    /** Trait instance for trait/pair subscriptions. */
+    instance?: TraitInstance;
+    /** Query instance for query add/remove subscriptions. */
+    query?: QueryInstance;
+};
+
+/* ------------------------------------------------------------------ *
+ * Pending command lookup
+ * ------------------------------------------------------------------ */
+
+/**
+ * Concatenated pending commands for an entity, in execution order (scopes
+ * from oldest to newest, commands in deferred order).
+ * Returns undefined when the entity has no pending commands.
+ */
+export function getDeferredEntityCommands(
+    ctx: WorldInternal,
+    entity: Entity
+): DeferredCommand[] | undefined {
+    if (!ctx.deferredEntitySet.has(entity)) return undefined;
+    const commands: DeferredCommand[] = [];
+    for (const scope of ctx.deferredScopes) {
+        const list = scope.byEntity.get(entity);
+        if (!list) continue;
+        for (let i = 0; i < list.length; i++) commands.push(list[i]);
+    }
+    return commands.length > 0 ? commands : undefined;
+}
+
+/**
+ * True when the entity has a pending deferred destroy (and no pending spawn
+ * to nullify it).
+ */
+export function isEntityDeferredDestroyed(ctx: WorldInternal, entity: Entity): boolean {
+    if (!ctx.deferredEntitySet.has(entity)) return false;
+    for (const scope of ctx.deferredScopes) {
+        const list = scope.byEntity.get(entity);
+        if (!list) continue;
+        for (let i = 0; i < list.length; i++) {
+            if (list[i].type === 'destroy') return true;
+        }
+    }
+    return false;
+}
+
+/* ------------------------------------------------------------------ *
+ * Raw (unbuffered) state reads
+ * ------------------------------------------------------------------ */
+
+/**
+ * Read the entity bitmask directly, ignoring any pending deferred commands.
+ */
+export function isTraitPresent(
+    ctx: WorldInternal,
+    entity: Entity,
+    trait: Trait
+): boolean {
+    const instance = getTraitInstance(ctx.traitInstances, trait);
+    if (!instance) return false;
+    const { generationId, bitflag } = instance;
+    const mask = ctx.entityMasks[generationId]?.[getEntityId(entity)] ?? 0;
+    return (mask & bitflag) === bitflag;
+}
+
+/**
+ * Read relation targets directly, ignoring any pending deferred commands.
+ */
+export function isPairPresent(
+    ctx: WorldInternal,
+    relation: Relation<Trait>,
+    entity: Entity,
+    target: Entity
+): boolean {
+    const relationCtx = relation[$internal];
+    const instance = getTraitInstance(ctx.traitInstances, relationCtx.trait);
+    if (!instance || !instance.relationTargets) return false;
+    const eid = getEntityId(entity);
+    if (relationCtx.exclusive) {
+        return (instance.relationTargets as Array<Entity | undefined>)[eid] === target;
+    }
+    const targets = (instance.relationTargets as number[][])[eid];
+    return targets ? targets.includes(target) : false;
+}
+
+/**
+ * Read the stored value of a trait directly from the store.
+ */
+function readRawTraitValue(ctx: WorldInternal, entity: Entity, trait: Trait): unknown {
+    const traitCtx = trait[$internal];
+    if (traitCtx.type === 'tag') return undefined;
+    const instance = getTraitInstance(ctx.traitInstances, trait);
+    if (!instance) return undefined;
+    const eid = getEntityId(entity);
+    if (traitCtx.type === 'aos') return (instance.store as unknown[])[eid];
+    const result: Record<string, unknown> = {};
+    const store = instance.store as Record<string, unknown[]>;
+    for (const key in store) result[key] = store[key][eid];
+    return result;
+}
+
+/**
+ * Read the stored value of a relation pair directly from the store.
+ */
+function readRawPairValue(
+    ctx: WorldInternal,
+    relation: Relation<Trait>,
+    entity: Entity,
+    target: Entity
+): unknown {
+    const relationCtx = relation[$internal];
+    const baseTrait = relationCtx.trait;
+    const baseCtx = baseTrait[$internal];
+    if (baseCtx.type === 'tag') return undefined;
+    const instance = getTraitInstance(ctx.traitInstances, baseTrait);
+    if (!instance || !instance.relationTargets) return undefined;
+    const eid = getEntityId(entity);
+    let index = -1;
+    if (relationCtx.exclusive) {
+        index = (instance.relationTargets as Array<Entity | undefined>)[eid] === target ? 0 : -1;
+    } else {
+        const rawTargets = (instance.relationTargets as number[][])[eid];
+        index = rawTargets ? rawTargets.indexOf(target) : -1;
+    }
+    if (index === -1) return undefined;
+    if (baseCtx.type === 'aos') {
+        if (relationCtx.exclusive) return (instance.store as unknown[])[eid];
+        return ((instance.store as unknown[][])[eid] ?? [])[index];
+    }
+    const result: Record<string, unknown> = {};
+    const store = instance.store as Record<string, Array<unknown | unknown[]>>;
+    for (const keyName in store) {
+        result[keyName] = (store[keyName][eid] as unknown[] | undefined)?.[index];
+    }
+    return result;
+}
+
+/* ------------------------------------------------------------------ *
+ * Replay of pending commands
+ * ------------------------------------------------------------------ */
+
+type DeferredReplayState = {
+    destroyed: boolean;
+    /** The entity was created by a pending deferred spawn. */
+    spawned: boolean;
+    /** Net trait presence after applying all pending commands. */
+    traits: Set<Trait>;
+    /** Net relation pairs after applying all pending commands. */
+    pairs: Map<Relation<Trait>, Entity[]>;
+    /** Final value of every present trait, applied sequentially. */
+    traitValues: Map<Trait, unknown>;
+    /** Final value of every present pair, applied sequentially. */
+    pairValues: Map<string, unknown>;
+};
+
+const pairKey = (traitId: number, target: Entity) => `${traitId}:${target}`;
+
+/**
+ * The value a freshly added trait will hold (mirrors the immediate
+ * addTrait initialization for a brand-new trait).
+ */
+function freshTraitValue(trait: Trait, params?: Record<string, unknown>): unknown {
+    const traitCtx = trait[$internal];
+    if (traitCtx.type === 'tag') return undefined;
+    if (traitCtx.type === 'aos') {
+        return params ?? getSchemaDefaults(trait.schema, 'aos');
+    }
+    const defaults = getSchemaDefaults(trait.schema, 'soa');
+    if (defaults) return { ...defaults, ...params };
+    return params;
+}
+
+/**
+ * The value a freshly added relation pair will hold (mirrors
+ * addRelationPairDirect for a brand-new pair).
+ */
+function freshPairValue(relation: Relation<Trait>, params?: Record<string, unknown>): unknown {
+    const baseTrait = relation[$internal].trait;
+    const baseCtx = baseTrait[$internal];
+    if (baseCtx.type === 'tag') return undefined;
+    const defaults = getSchemaDefaults(baseTrait.schema, baseCtx.type);
+    if (defaults) return { ...defaults, ...params };
+    return params;
+}
+
+function clearPairsForRelation(state: DeferredReplayState, relation: Relation<Trait>) {
+    const baseTrait = relation[$internal].trait;
+    const targets = state.pairs.get(relation);
+    if (targets) {
+        for (let i = 0; i < targets.length; i++) {
+            state.pairValues.delete(pairKey(baseTrait.id, targets[i]));
+        }
+    }
+    state.pairs.delete(relation);
+    state.traits.delete(baseTrait);
+}
+
+/**
+ * Apply a deferred add command (or the trait list of a spawn command) to the
+ * replay state. Values are folded sequentially so that later writes replace
+ * earlier ones.
+ */
+function applyPendingAdd(state: DeferredReplayState, configs: ConfigurableTrait[]) {
+    for (const config of configs) {
+        // A stray plain params object carries no trait of its own.
+        if (typeof config === 'object' && config !== null && !Array.isArray(config) && !isRelationPair(config)) {
+            continue;
+        }
+        if (isRelationPair(config)) {
+            const pairCtx = config[$internal];
+            const relation = pairCtx.relation as Relation<Trait>;
+            const target = pairCtx.target;
+            const params = pairCtx.params;
+            // Only specific targets can be added (not wildcard '*').
+            if (typeof target !== 'number') continue;
+
+            const relationCtx = relation[$internal];
+            const baseTrait = relationCtx.trait;
+            let targets = state.pairs.get(relation);
+            if (!targets) {
+                targets = [];
+                state.pairs.set(relation, targets);
+            }
+            const exists = targets.includes(target);
+
+            if (relationCtx.exclusive) {
+                // Exclusive relations: a new target replaces the old one.
+                if (!exists) {
+                    const oldTarget = targets[0];
+                    if (oldTarget !== undefined) {
+                        state.pairValues.delete(pairKey(baseTrait.id, oldTarget));
+                    }
+                    targets.length = 0;
+                    targets.push(target);
+                    // A brand-new pair reinitializes its store slot.
+                    state.pairValues.set(pairKey(baseTrait.id, target), freshPairValue(relation, params));
+                }
+            } else if (!exists) {
+                targets.push(target);
+                state.pairValues.set(pairKey(baseTrait.id, target), freshPairValue(relation, params));
+            }
+            state.traits.add(baseTrait);
+            continue;
+        }
+
+        const trait = Array.isArray(config) ? config[0] : config;
+        const params = Array.isArray(config) ? config[1] : undefined;
+        if (!state.traits.has(trait)) {
+            state.traits.add(trait);
+            state.traitValues.set(trait, freshTraitValue(trait, params));
+        } else if (params) {
+            const traitCtx = trait[$internal];
+            if (traitCtx.type === 'soa') {
+                // A plain params object only writes the fields it carries;
+                // the later values replace the earlier ones field by field.
+                const current = state.traitValues.get(trait);
+                state.traitValues.set(trait, {
+                    ...(current as Record<string, unknown> | undefined),
+                    ...params,
+                });
+            } else if (traitCtx.type === 'aos') {
+                // A new value replaces the stored object wholesale.
+                state.traitValues.set(trait, params);
+            }
+            // tag: no data to replace
+        }
+    }
+}
+
+function applyPendingRemove(state: DeferredReplayState, traits: (Trait | RelationPair)[]) {
+    for (const trait of traits) {
+        if (isRelationPair(trait)) {
+            const relation = trait[$internal].relation as Relation<Trait>;
+            const target = trait[$internal].target;
+            const relationCtx = relation[$internal];
+            const baseTrait = relationCtx.trait;
+
+            if (target === '*') {
+                clearPairsForRelation(state, relation);
+                continue;
+            }
+            if (typeof target !== 'number') continue;
+
+            const targets = state.pairs.get(relation);
+            if (!targets) continue;
+            const idx = targets.indexOf(target);
+            if (idx === -1) continue;
+            targets.splice(idx, 1);
+            state.pairValues.delete(pairKey(baseTrait.id, target));
+            if (targets.length === 0) {
+                state.pairs.delete(relation);
+                state.traits.delete(baseTrait);
+            }
+            continue;
+        }
+
+        state.traits.delete(trait);
+        state.traitValues.delete(trait);
+        const relation = trait[$internal].relation;
+        if (relation) clearPairsForRelation(state, relation as Relation<Trait>);
+    }
+}
+
+/**
+ * Replay the pending commands for an entity to compute its state after the
+ * pending flush. Returns undefined when the entity has no pending commands.
+ */
+export function replayDeferredState(
+    ctx: WorldInternal,
+    entity: Entity
+): DeferredReplayState | undefined {
+    const commands = getDeferredEntityCommands(ctx, entity);
+    if (!commands) return undefined;
+
+    const state: DeferredReplayState = {
+        destroyed: false,
+        spawned: false,
+        traits: new Set(),
+        pairs: new Map(),
+        traitValues: new Map(),
+        pairValues: new Map(),
+    };
+
+    const eid = getEntityId(entity);
+    let startIndex = 0;
+
+    if (commands[0].type === 'spawn') {
+        // The entity does not exist yet: start from an empty state and apply
+        // the spawn command's traits as the initial set.
+        state.spawned = true;
+        applyPendingAdd(state, commands[0].traits);
+        startIndex = 1;
+    } else {
+        // Seed with the current, unbuffered world state.
+        const currentTraits = ctx.entityTraits.get(entity);
+        if (currentTraits) {
+            for (const trait of currentTraits) {
+                state.traits.add(trait);
+                state.traitValues.set(trait, readRawTraitValue(ctx, entity, trait));
+            }
+        }
+        for (const relation of ctx.relations) {
+            const baseTrait = relation[$internal].trait;
+            if (!state.traits.has(baseTrait)) continue;
+            const instance = getTraitInstance(ctx.traitInstances, baseTrait);
+            const relationTargets = instance?.relationTargets;
+            if (!relationTargets) continue;
+            const raw = (relationTargets as (number | number[])[])[eid];
+            if (raw === undefined || raw === null) continue;
+            const targets = (Array.isArray(raw) ? raw.slice() : [raw]) as Entity[];
+            if (targets.length === 0) continue;
+            state.pairs.set(relation, targets);
+            for (let i = 0; i < targets.length; i++) {
+                state.pairValues.set(pairKey(baseTrait.id, targets[i]), readRawPairValue(ctx, relation, entity, targets[i]));
+            }
+        }
+    }
+
+    for (let i = startIndex; i < commands.length; i++) {
+        if (state.destroyed) break;
+        const command = commands[i];
+        switch (command.type) {
+            case 'destroy':
+                state.destroyed = true;
+                state.traits.clear();
+                state.pairs.clear();
+                state.traitValues.clear();
+                state.pairValues.clear();
+                break;
+            case 'add':
+                applyPendingAdd(state, command.traits);
+                break;
+            case 'remove':
+                applyPendingRemove(state, command.traits);
+                break;
+            case 'addExclusive': {
+                clearPairsForRelation(state, command.relation);
+                if (command.target !== '*') {
+                    state.pairs.set(command.relation, [command.target]);
+                    const baseTrait = command.relation[$internal].trait;
+                    state.pairValues.set(
+                        pairKey(baseTrait.id, command.target),
+                        freshPairValue(command.relation, command.params)
+                    );
+                    state.traits.add(baseTrait);
+                }
+                break;
+            }
+        }
+    }
+
+    return state;
+}
+
+/* ------------------------------------------------------------------ *
+ * Flush-aware has / get
+ * ------------------------------------------------------------------ */
+
+/**
+ * The result `entity.has(trait)` should report while commands are pending.
+ * Returns undefined when the entity has no pending commands.
+ */
+export function getDeferredTraitHas(
+    ctx: WorldInternal,
+    entity: Entity,
+    trait: Trait
+): boolean | undefined {
+    const state = replayDeferredState(ctx, entity);
+    if (!state) return undefined;
+    return state.destroyed ? false : state.traits.has(trait);
+}
+
+/**
+ * The result `entity.get(trait)` should report while commands are pending.
+ * Returns undefined when the entity has no pending commands.
+ */
+export function getDeferredTraitValue(
+    ctx: WorldInternal,
+    entity: Entity,
+    trait: Trait
+): { value: unknown } | undefined {
+    const state = replayDeferredState(ctx, entity);
+    if (!state) return undefined;
+    if (state.destroyed || !state.traits.has(trait)) return { value: undefined };
+
+    const traitCtx = trait[$internal];
+    if (traitCtx.type === 'tag') return { value: undefined };
+    return { value: state.traitValues.get(trait) };
+}
+
+/**
+ * The result `entity.has(relation(target))` should report while commands are
+ * pending. Returns undefined when the entity has no pending commands.
+ */
+export function getDeferredPairHas(
+    ctx: WorldInternal,
+    entity: Entity,
+    relation: Relation<Trait>,
+    target: RelationTarget
+): boolean | undefined {
+    const state = replayDeferredState(ctx, entity);
+    if (!state) return undefined;
+    if (state.destroyed) return false;
+    const baseTrait = relation[$internal].trait;
+    if (target === '*') return state.traits.has(baseTrait);
+    const targets = state.pairs.get(relation);
+    return targets ? targets.includes(target) : false;
+}
+
+/**
+ * The result `entity.get(relation(target))` should report while commands are
+ * pending. Returns undefined when the entity has no pending commands.
+ */
+export function getDeferredPairValue(
+    ctx: WorldInternal,
+    entity: Entity,
+    relation: Relation<Trait>,
+    target: Entity
+): { value: unknown } | undefined {
+    const state = replayDeferredState(ctx, entity);
+    if (!state) return undefined;
+    if (state.destroyed) return { value: undefined };
+
+    const relationCtx = relation[$internal];
+    const baseTrait = relationCtx.trait;
+    const targets = state.pairs.get(relation);
+    if (!targets || !targets.includes(target)) return { value: undefined };
+    if (baseTrait[$internal].type === 'tag') return { value: undefined };
+    return { value: state.pairValues.get(pairKey(baseTrait.id, target)) };
+}
+
+/* ------------------------------------------------------------------ *
+ * Subscription recording (suppression during flush)
+ * ------------------------------------------------------------------ */
+
+/**
+ * Fire a subscription now, or record it when a deferred flush is in progress.
+ * Recorded events are diffed against the pre-flush state so that each
+ * subscription fires at most once, based on the state difference before and
+ * after the flush.
+ */
+export function noteOrFireTraitSubscriptions(
+    world: { [$internal]: WorldInternal },
+    entity: Entity,
+    instance: TraitInstance,
+    target: Entity | undefined,
+    isAdd: boolean,
+    pre: boolean
+): void {
+    const ctx = world[$internal];
+    const subs = isAdd ? instance.addSubscriptions : instance.removeSubscriptions;
+    if (ctx.deferredFlushDepth > 0) {
+        const key =
+            target === undefined
+                ? `${entity}:${instance.trait.id}`
+                : `${entity}:${instance.trait.id}:${target}`;
+        const touched = ctx.deferredTouchedStack[ctx.deferredTouchedStack.length - 1];
+        if (!touched.has(key)) {
+            touched.set(key, { key, entity, target, instance, pre });
+        }
+        return;
+    }
+    for (const sub of subs) sub(entity, target);
+}
+
+/**
+ * Fire a query subscription now, or record it when a deferred flush is in
+ * progress.
+ */
+export function noteOrFireQuerySubscriptions(
+    world: { [$internal]: WorldInternal },
+    entity: Entity,
+    query: QueryInstance,
+    isAdd: boolean,
+    pre: boolean
+): void {
+    const ctx = world[$internal];
+    const subs = isAdd ? query.addSubscriptions : query.removeSubscriptions;
+    if (ctx.deferredFlushDepth > 0) {
+        // No state change to record.
+        if (pre) return;
+        const key = `q:${entity}:${query.hash}`;
+        const touched = ctx.deferredTouchedStack[ctx.deferredTouchedStack.length - 1];
+        if (!touched.has(key)) {
+            touched.set(key, { key, entity, query, pre });
+        }
+        return;
+    }
+    for (const sub of subs) sub(entity);
+}
+
+/**
+ * Fire the recorded subscription events based on the state difference
+ * between before and after the flushed commands.
+ */
+export function fireDeferredSubscriptionDiff(
+    ctx: WorldInternal,
+    touched: Map<string, TouchedSubscription>
+): void {
+    if (touched.size === 0) return;
+
+    for (const rec of touched.values()) {
+        let post: boolean;
+        if (rec.query) {
+            post = rec.query.entities.has(rec.entity) && !rec.query.toRemove.has(rec.entity);
+        } else if (rec.target !== undefined && rec.instance) {
+            const relation = rec.instance.trait[$internal].relation as Relation<Trait> | null;
+            post = relation
+                ? isPairPresent(ctx, relation, rec.entity, rec.target)
+                : isTraitPresent(ctx, rec.entity, rec.instance.trait);
+        } else if (rec.instance) {
+            post = isTraitPresent(ctx, rec.entity, rec.instance.trait);
+        } else {
+            continue;
+        }
+
+        if (post === rec.pre) continue;
+
+        const subs = rec.query
+            ? post
+                ? rec.query.addSubscriptions
+                : rec.query.removeSubscriptions
+            : post
+              ? rec.instance!.addSubscriptions
+              : rec.instance!.removeSubscriptions;
+        for (const sub of subs) sub(rec.entity, rec.target);
+    }
+
+    touched.clear();
+}
