+    if (index !== -1) ctx.deferredScopes.splice(index, 1);
+    if (scope.commands.length === 0) return;
+    executeDeferredCommands(world, scope.commands);
+    scope.commands.length = 0;
+    scope.byEntity.clear();
+}
+
+/**
+ * Flush the scope (e.g. at the exit of an updateEach pass).
+ */
+export function flushDeferredScope(world: World, scope: DeferredScope): void {
+    detachAndExecuteDeferredScope(world, scope);
+}
+
+/**
+ * Flush the current (top) scope. A fresh empty scope replaces it so that
+ * top-level buffers keep working after a flush.
+ */
+export function flushTopDeferredScope(world: World): void {
+    const ctx = world[$internal];
+    const scope = ctx.deferredScopes[ctx.deferredScopes.length - 1];
