+    let index = 0;
+    try {
+        for (; index < commands.length; index++) {
+            executeDeferredCommand(world, commands[index]);
+        }
+    } catch (error) {
+        // Drop the failing command and keep the commands that never ran
+        // pending in a new scope.
+        requeueDeferredCommands(world, commands.slice(index + 1));
+        ctx.deferredTouchedStack.pop();
+        fireDeferredSubscriptionDiff(ctx, touched);
+        cleanDeferredEntitySet(world, affected);
+        ctx.deferredFlushDepth--;
+        throw error;
+    }
+
+    ctx.deferredTouchedStack.pop();
+    fireDeferredSubscriptionDiff(ctx, touched);
+    cleanDeferredEntitySet(world, affected);
+    ctx.deferredFlushDepth--;
+}
+
+/**
+ * An entity slot is "initialized" once its traits and bookkeeping exist.
+ * Slots allocated eagerly for pending spawn commands are alive but not yet
+ * initialized, and commands targeting them must be skipped (the spawn
+ * command is what brings them to life).
+ */
+function isEntityInitialized(ctx: WorldInternal, entity: Entity): boolean {
+    return isEntityAlive(ctx.entityIndex, entity) && ctx.entityTraits.has(entity);
+}
+
+function executeDeferredCommand(world: World, command: DeferredCommand): void {
+    const ctx = world[$internal];
+
+    switch (command.type) {
+        case 'spawn': {
+            // The entity slot was allocated when the command was deferred; a
+            // destroyed slot means it was recycled and must be skipped.
+            if (!isEntityAlive(ctx.entityIndex, command.entity)) return;
+            initializeEntity(world, command.entity, command.traits);
+            return;
+        }
+        case 'destroy': {
+            if (command.entity === ctx.worldEntity) {
+                throw new Error('Koota: The world entity cannot be destroyed.');
+            }
+            if (!isEntityInitialized(ctx, command.entity)) return;
+            destroyEntity(world, command.entity);
+            return;
+        }
+        case 'add': {
+            if (!isEntityInitialized(ctx, command.entity)) return;
+            for (const config of command.traits) {
+                if (isPlainParams(config)) continue;
+                if (isRelationPair(config)) {
+                    const pairCtx = config[$internal];
+                    const target = pairCtx.target;
+                    // Only specific targets can be added (not wildcard '*').
+                    if (typeof target !== 'number') continue;
+                    addRelationPairDirect(
+                        world,
+                        command.entity,
+                        pairCtx.relation as Relation<Trait>,
+                        target,
+                        pairCtx.params
+                    );
+                    continue;
+                }
+                const trait = Array.isArray(config) ? config[0] : config;
+                const params = Array.isArray(config) ? config[1] : undefined;
+                if (hasTraitRaw(world, command.entity, trait)) {
+                    // Later values for the same trait replace earlier ones.
+                    if (params !== undefined) replaceDeferredValue(world, command.entity, trait, params);
+                } else {
+                    addTrait(world, command.entity, config);
+                }
+            }
+            return;
+        }
+        case 'remove': {
+            if (!isEntityInitialized(ctx, command.entity)) return;
+            for (const trait of command.traits) removeTrait(world, command.entity, trait);
+            return;
+        }
+        case 'addExclusive': {
+            if (!isEntityInitialized(ctx, command.entity)) return;
+            const { relation, target, params } = command;
+            if (target === '*') {
+                // Wildcard clears all pairs.
+                removeRelationPairDirect(world, command.entity, relation, '*');
+            } else {
+                // Replace all existing pairs with the single new one.
+                const existing = getRelationTargets(world, relation, command.entity);
+                for (const existingTarget of existing) {
+                    removeRelationPairDirect(world, command.entity, relation, existingTarget);
+                }
+                addRelationPairDirect(world, command.entity, relation, target, params);
+            }
+            return;
+        }
+    }
+}
+
+/**
+ * Replace the value of an already-present trait (deferred "replace"
+ * semantics). Mirrors what a fresh add with params would write.
+ */
+function replaceDeferredValue(
+    world: World,
+    entity: Entity,
+    trait: Trait,
+    params: Record<string, unknown>
+): void {
+    const traitCtx = trait[$internal];
+    if (traitCtx.type === 'tag') return;
+    // For soa traits only the fields present in params are written, so the
+    // later values replace the earlier ones field by field; for aos the new
+    // value replaces the stored object wholesale.
+    setTrait(world, entity, trait, params, false);
+}
+
+/* ------------------------------------------------------------------ *
+ * Public deferred API
+ * ------------------------------------------------------------------ */
+
+/** A config accepted by the loose forms of the deferred API. */
+export type DeferredConfig = ConfigurableTrait | Record<string, unknown>;
+
+export type Deferred = {
+    spawn: (...traits: DeferredConfig[]) => Entity;
+    destroy: (entity: Entity) => void;
+    add: (entity: Entity, ...traits: DeferredConfig[]) => void;
+    remove: (entity: Entity, ...traits: (Trait | RelationPair)[]) => void;
+    addExclusive: (
+        entity: Entity,
+        relationOrPair: Relation<Trait> | RelationPair,
+        target?: RelationTarget,
+        params?: Record<string, unknown>
+    ) => void;
+    flush: () => void;
+};
+
+/**
+ * A plain params object (not an array, not a relation pair).
+ */
+function isPlainParams(value: unknown): value is Record<string, unknown> {
+    return (
+        typeof value === 'object' && value !== null && !Array.isArray(value) && !isRelationPair(value)
+    );
+}
+
+function isBareTrait(value: unknown): value is Trait {
+    return typeof value === 'function' && !isRelation(value);
+}
+
+/**
+ * Accept the loose `T, params` and `relation(target), params` call forms by
+ * merging a plain params object into the config that precedes it.
+ */
+function normalizeDeferredConfigs(configs: unknown[]): ConfigurableTrait[] {
+    const out: ConfigurableTrait[] = [];
+    for (const config of configs) {
+        if (isPlainParams(config) && out.length > 0) {
+            const prev = out[out.length - 1];
+            if (isBareTrait(prev)) {
+                out[out.length - 1] = [prev, config];
+                continue;
+            }
+            if (Array.isArray(prev) && isBareTrait(prev[0])) {
+                const [trait, params] = prev;
+                out[out.length - 1] = [trait, { ...params, ...config }];
+                continue;
+            }
+            if (isRelationPair(prev)) {
+                const pairCtx = prev[$internal];
+                out[out.length - 1] = {
+                    [$relationPair]: true,
+                    [$internal]: {
+                        relation: pairCtx.relation,
+                        target: pairCtx.target,
+                        params: { ...pairCtx.params, ...config },
+                    },
+                };
+                continue;
+            }
+        }
+        out.push(config as ConfigurableTrait);
+    }
+    return out;
+}
+
+export function createDeferredBuffer(world: World): Deferred {
+    return {
+        spawn(...traits: DeferredConfig[]): Entity {
+            const ctx = world[$internal];
+            // Allocate the slot eagerly so the caller receives a usable entity
+            // reference before the buffer flushes. Traits and query
+            // registrations are applied when the command executes.
+            const entity = allocateEntity(ctx.entityIndex);
+            pushDeferredCommand(ctx, { type: 'spawn', entity, traits: normalizeDeferredConfigs(traits) });
+            return entity;
+        },
+
+        destroy(entity: Entity) {
+            const ctx = world[$internal];
+            // A spawn and a destroy in the same buffer nullify each other:
+            // the entity is never created, so both commands are dropped and
+            // the eagerly-allocated slot is released. Scopes are separate
+            // buffers, so only a spawn in the current scope is nullified.
+            const scope = currentScope(ctx);
+            const commands = scope.byEntity.get(entity);
+            if (commands) {
+                const spawn = commands.find((command) => command.type === 'spawn');
+                if (spawn) {
+                    removeDeferredCommand(ctx, spawn);
+                    releaseEntity(ctx.entityIndex, entity);
+                    return;
+                }
+            }
+            pushDeferredCommand(ctx, { type: 'destroy', entity });
+        },
+
+        add(entity: Entity, ...traits: DeferredConfig[]) {
+            pushDeferredCommand(world[$internal], {
+                type: 'add',
+                entity,
+                traits: normalizeDeferredConfigs(traits),
+            });
+        },
+
+        remove(entity: Entity, ...traits: (Trait | RelationPair)[]) {
+            pushDeferredCommand(world[$internal], { type: 'remove', entity, traits });
+        },
+
+        addExclusive(
+            entity: Entity,
+            relationOrPair: Relation<Trait> | RelationPair,
+            target?: RelationTarget,
+            params?: Record<string, unknown>
+        ) {
+            let relation: Relation<Trait>;
+            let pairTarget: RelationTarget | undefined;
+            let pairParams: Record<string, unknown> | undefined;
+
+            if (isRelationPair(relationOrPair)) {
+                const pairCtx = relationOrPair[$internal];
+                relation = pairCtx.relation as Relation<Trait>;
+                pairTarget = pairCtx.target;
+                pairParams = pairCtx.params;
+            } else {
+                relation = relationOrPair;
+                pairTarget = target;
+                pairParams = params;
+            }
+
+            if (pairTarget === undefined) {
+                throw new Error('Relation target is undefined');
+            }
+
+            pushDeferredCommand(world[$internal], {
+                type: 'addExclusive',
+                entity,
+                relation,
+                target: pairTarget,
+                params: pairParams,
+            });
+        },
+
+        flush() {
+            flushTopDeferredScope(world);
+        },
+    };
+}
