+
+describe('Deferred', () => {
+    beforeEach(() => {
+        universe.reset();
+    });
+
+    describe('buffering basics', () => {
+        it('defers spawn until flush', () => {
+            const A = trait();
+            const world = createWorld();
+            const before = world.entities.length;
+
+            const e = world.deferred.spawn(A);
+            // Allocated eagerly so the reference is usable, but not registered
+            // with traits/queries until flush.
+            expect(world.query(A).length).toBe(0);
+
+            world.deferred.flush();
+            expect(world.query(A).length).toBe(1);
+            expect(e.has(A)).toBe(true);
+            expect(world.entities.length).toBe(before + 1);
+        });
+
+        it('defers add / remove until flush', () => {
+            const A = trait();
+            const B = trait();
+            const world = createWorld();
+            const e = world.spawn();
+
+            world.deferred.add(e, A);
+            expect(world.query(A).length).toBe(0);
+            world.deferred.remove(e, A);
+            world.deferred.add(e, B);
+            expect(world.query(B).length).toBe(0);
+
+            world.deferred.flush();
+            expect(e.has(A)).toBe(false);
+            expect(e.has(B)).toBe(true);
+        });
+
+        it('does nothing on flush when the buffer is empty', () => {
+            const world = createWorld();
+            expect(() => world.deferred.flush()).not.toThrow();
+        });
+    });
+
+    describe('ordering and replacement', () => {
+        it('executes earlier-deferred commands before later ones', () => {
+            const A = trait();
+            const world = createWorld();
+            const e = world.spawn();
+
+            world.deferred.add(e, A);
+            world.deferred.remove(e, A);
+            world.deferred.flush();
+            expect(e.has(A)).toBe(false);
+
+            const f = world.spawn();
+            world.deferred.add(f, A);
+            world.deferred.flush();
+            expect(f.has(A)).toBe(true);
+        });
+
+        it('later values for the same trait replace earlier ones', () => {
+            const T = trait({ x: 0, y: 0 });
